/* Leituras editoriais e explicações geradas a partir dos campos do catálogo.
 * A explicação não substitui efeitos, condições e erratas do texto oficial. */
(() => {
  const editorial = {
    'OP01-001': {title:'Um capitão para pressionar com a tripulação.',text:'Com pelo menos um DON!! atribuído a Zoro, seus Personagens recebem +1000 de poder durante o seu turno. O aumento alcança o campo inteiro: vale comparar quantos ataques adicionais se tornam relevantes antes de distribuir os outros DON!!.',watch:'O bônus vem da condição do Líder e não substitui o aumento normal dos DON!! atribuídos a cada carta.'},
    'OP01-002': {title:'Troque peças e mantenha o campo em movimento.',text:'Com cinco Personagens em campo, a habilidade de Law permite pagar dois DON!!, devolver um dos seus Personagens à mão e depois jogar da mão até um Personagem de custo cinco ou menos de cor diferente da carta devolvida. Essa troca pode reaproveitar efeitos de entrada e reorganizar o campo.',watch:'A habilidade é uma vez por turno. Confira a quantidade de Personagens e a diferença de cor exigidas antes de pagar o custo.'},
    'OP01-003': {title:'Uma nova chance para uma peça importante.',text:'Este Líder vermelho e verde pode, uma vez por turno na fase principal, pagar quatro DON!! para reativar até um dos seus Personagens Supernovas ou Straw Hat Crew de custo cinco ou menos. A carta escolhida também recebe +1000 de poder durante o turno.',watch:'Reativar uma carta não remove, por si só, a restrição de atacar no turno em que ela entrou.'},
    'OP01-004': {title:'Uma ameaça pequena com uma escolha defensiva.',text:'Usopp combina custo dois, 3000 de poder e Counter +2000. Com um DON!! atribuído, durante o seu turno ele compra uma carta quando o oponente ativa um Evento, respeitando o limite de uma vez por turno. Na mão, o Counter oferece outra utilização possível.',watch:'A compra não acontece a cada Evento sem limite: observe a condição de turno e a limitação do efeito.'},
    'OP01-006': {title:'Enfraqueça o alvo antes do próximo movimento.',text:'Otama custa um DON!! e, ao ser jogada, reduz em 2000 o poder de até um Personagem adversário durante aquele turno. Essa redução pode mudar uma comparação de combate ou ajudar outra carta que exija um limite de poder. Seu Counter +2000 também permite usá-la defensivamente da mão.',watch:'Reduzir poder não causa K.O. automaticamente. Poder base zero não impede que uma carta permaneça no campo.'},
    'OP01-016': {title:'Encontre outra peça dos Chapéus de Palha.',text:'Ao entrar, Nami olha as cinco cartas do topo do seu deck e permite revelar e adicionar à mão até uma carta Straw Hat Crew que não seja Nami. As outras cartas vão ao fundo do deck na ordem que você escolher. É uma maneira de procurar uma peça dentro desse grupo específico.',watch:'A busca não encontra qualquer carta: a característica e a exclusão de Nami fazem parte do efeito.'},
    'OP01-025': {title:'Entre em campo e entre na batalha.',text:'Zoro transforma três DON!! em um Personagem de 5000 de poder com Rush. Isso permite que ataque no turno em que é jogado, criando pressão imediata sem precisar esperar a próxima rodada. Como não tem Counter impresso, ficar com ele na mão não oferece o aumento defensivo de um Counter.',watch:'Rush não ignora a regra que impede cada jogador de atacar no próprio primeiro turno.'},
    'OP01-029': {title:'Um recurso de defesa que cresce com a urgência.',text:'Radical Beam!! é um Evento de Counter de custo um. Ele dá +2000 de poder a até um dos seus Líderes ou Personagens durante a batalha e acrescenta mais +2000 se você tiver duas ou menos cartas de vida. Seu Trigger possui outro efeito: +1000 de poder durante o turno para até um dos seus Líderes ou Personagens.',watch:'O efeito normal e o Trigger têm valores e durações diferentes. Não aplique os dois como se fossem uma única ativação.'},
    'OP01-060': {title:'O topo do deck pode virar uma nova peça.',text:'Ao atacar com dois DON!! atribuídos, Doflamingo pode pagar um DON!! para revelar a carta do topo do deck. Se ela for um Personagem The Seven Warlords of the Sea de custo quatro ou menos, o efeito permite jogá-la descansada. Conhecer ou organizar o topo pode tornar essa jogada mais previsível.',watch:'A carta entra descansada. Confira a característica e o custo revelados; uma carta incompatível não é jogada por esse efeito.'},
    'OP01-061': {title:'Transforme um K.O. em mais recursos.',text:'Com um DON!! atribuído a este Líder, durante o seu turno e uma vez por turno, o K.O. de um Personagem adversário permite adicionar até um DON!! ativo do seu deck de DON!!. A habilidade conecta a remoção de uma peça adversária à expansão de seus recursos.',watch:'É necessário haver DON!! disponível no deck de DON!!; enviar uma carta ao descarte por outro método não equivale necessariamente a K.O.'},
    'OP01-062': {title:'Eventos que ajudam a repor a mão.',text:'Com um DON!! atribuído, Crocodile permite comprar uma carta quando você ativa um Evento, desde que tenha quatro ou menos cartas na mão e ainda não tenha comprado por essa habilidade naquele turno. A proposta é acompanhar o uso de Eventos com reposição de recursos.',watch:'Confira o tamanho da mão e o limite do Líder. Ativar um Trigger não equivale automaticamente a ativar um Evento.'},
    'OP01-091': {title:'Prepare dez DON!! e reduza a resistência do campo.',text:'King diminui em 1000 o poder de todos os Personagens adversários durante o seu turno enquanto você tem dez DON!! no campo. A condição observa os recursos em campo, não exige que todos estejam ativos. O efeito pode alterar diversos combates no mesmo turno.',watch:'O texto não reduz o poder do Líder adversário. Se a condição de dez DON!! deixar de ser satisfeita, confira a aplicação do efeito permanente.'},
    'OP01-094': {title:'Uma entrada que muda o campo inteiro.',text:'Este Kaido custa dez DON!! e tem 12000 de poder. Ao entrar, você pode devolver seis DON!! ao deck de DON!! para aplicar seu efeito, caso seu Líder seja Animal Kingdom Pirates: todos os Personagens além deste Kaido sofrem K.O. Isso inclui os seus outros Personagens.',watch:'O efeito alcança os dois campos. Considere as suas próprias peças, os recursos devolvidos e eventuais proteções antes de resolver.'},
    'OP01-120': {title:'Pressão imediata com uma restrição aos bloqueadores.',text:'Shanks entra por nove DON!! com 10000 de poder e Rush. Ao atacar, impede o oponente de ativar Personagens com Blocker que tenham 2000 ou menos de poder durante aquela batalha. A restrição pode abrir espaço para um ataque importante.',watch:'Esse texto não impede todos os Blockers: o limite de poder indicado é essencial.'},
    'OP02-001': {title:'Mais vida inicial, com uma conta ao fim do turno.',text:'Edward.Newgate começa com seis cartas de vida e 6000 de poder base. Em compensação, ao fim do seu turno o efeito adiciona uma carta do topo da sua vida à sua mão. O recurso que aumenta a mão também diminui a reserva de vida.',watch:'Adicionar vida à mão por esse efeito não é receber dano e não abre a janela normal de Trigger.'},
    'OP02-013': {title:'Enfraqueça dois alvos e avalie a entrada com Rush.',text:'Ao entrar, Ace reduz em 3000 o poder de até dois Personagens adversários durante o turno. Depois, se a característica do seu Líder incluir Whitebeard Pirates, Ace ganha Rush naquele turno. A condição do Líder determina se ele poderá pressionar imediatamente.',watch:'Rush é condicional nesta carta. Ter a palavra no texto não significa que toda ativação conceda a habilidade.'},
    'OP03-040': {title:'Uma condição de vitória que muda o destino do deck.',text:'Esta Nami substitui a derrota normal por deck vazio por uma vitória quando seu deck chega a zero, conforme seu efeito. Com um DON!! atribuído, quando o ataque do Líder causa dano à vida adversária, você pode enviar uma carta do topo do seu deck ao descarte.',watch:'A condição de vitória depende do efeito válido da carta. Confira interações que neguem efeitos e a FAQ oficial.'},
    'OP03-099': {title:'Informação sobre a vida antes de decidir o ataque.',text:'Com um DON!! atribuído, ao atacar Katakuri permite olhar até uma carta do topo da sua vida ou da vida adversária e colocá-la no topo ou no fundo da respectiva vida. Depois, o Líder recebe +1000 de poder naquela batalha. A habilidade combina informação e ajuste de posição.',watch:'O aumento do efeito dura aquela batalha. Não se confunde com o bônus normal do DON!! atribuído durante o seu turno.'},
    'OP04-112': {title:'O total de vida define o alcance da remoção.',text:'Ao entrar, Yamato pode causar K.O. em até um Personagem adversário com custo igual ou inferior à soma das cartas de vida dos dois jogadores. Depois, se você tiver uma ou nenhuma carta de vida, pode adicionar até uma carta do topo do seu deck ao topo da sua vida.',watch:'O alvo é limitado pelo total de cartas de vida, não pelo poder. A segunda parte observa somente a sua quantidade de vida.'},
    'OP05-060': {title:'Troque uma carta de vida por aceleração.',text:'Uma vez por turno na fase principal, este Luffy permite adicionar uma carta do topo da sua vida à mão como custo. Se você tiver zero ou pelo menos três DON!! em campo, adiciona até um DON!! ativo do deck de DON!!. A quantidade em campo define quando a aceleração ocorre.',watch:'É uma troca entre sua reserva de vida e seus recursos. O requisito não é simplesmente “ter qualquer quantidade de DON!!”.'},
    'OP05-119': {title:'Um turno extra com um investimento enorme.',text:'Ao jogar este Luffy, você pode devolver dez DON!! e colocar os seus outros Personagens no fundo do deck para receber um turno extra depois do atual. Ele permanece como a principal peça do campo. A outra habilidade permite pagar um DON!!, uma vez por turno na fase principal, para adicionar até um DON!! ativo do deck de DON!!.',watch:'Devolver dez DON!! e reorganizar seus Personagens são partes importantes da jogada; não leia apenas a frase do turno extra.'},
    'OP06-022': {title:'Dois danos e uma nova utilização para DON!! descansados.',text:'Esta Yamato tem Double Attack: quando o ataque causa dano à vida, são dois danos em vez de um. Uma vez por turno na fase principal, se o oponente tiver três ou menos cartas de vida, a habilidade atribui até dois DON!! descansados a um dos seus Personagens.',watch:'Double Attack não são dois ataques separados e não converte automaticamente uma única vida restante em derrota naquele ataque.'},
    'OP09-118': {title:'Um ataque que exige cuidado na decisão de bloquear.',text:'Roger custa dez DON!!, tem 13000 de poder e Rush. Seu outro efeito estabelece uma condição especial: quando o oponente ativa Blocker, se você ou ele tiver zero cartas de vida, você vence a partida. A decisão de bloquear precisa considerar essa condição.',watch:'O texto não declara vitória só porque alguém está com zero de vida: a ativação adversária de Blocker é parte do evento exigido.'},
    'EB01-011': {title:'Uma embarcação para transformar uma peça em compra.',text:'Mini-Merry é um Cenário de custo um. Na fase principal, seu efeito permite descansar este Cenário e colocar um dos seus Personagens com 1000 de poder base no fundo do deck como custo para comprar uma carta.',watch:'O requisito é poder base, não o poder atual depois de bônus e reduções.'}
  };
  const glossary = {
    'Rush': ['Rush','Permite que um Personagem ataque no turno em que é jogado. Não ignora a proibição de atacar no primeiro turno de cada jogador.'],
    'Rush: Character': ['Rush: Character','A permissão imediata se refere a atacar Personagens. Não equivale à permissão geral de Rush para atacar o Líder.'],
    'Blocker': ['Blocker','Pode mudar o alvo de um ataque para um Personagem elegível ao descansá-lo na etapa de bloqueio. Leia quem possui ou recebe essa habilidade e suas condições.'],
    'Double Attack': ['Double Attack','Faz um ataque que cause dano à vida provocar dois danos em vez de um. É um ataque, não duas declarações de ataque.'],
    'Banish': ['Banish','Quando o ataque causa dano à vida, a carta de vida vai ao descarte em vez da mão e seu Trigger não é ativado.'],
    'Unblockable': ['Unblockable','Impede a ativação de Blocker contra o ataque ao qual a habilidade se aplica.'],
    'Trigger': ['Trigger','É uma possibilidade de efeito ao verificar uma carta de vida por dano. O efeito de Trigger é separado do efeito normal da carta.']
  };
  const timings = {
    'On Play':['Ao entrar em jogo','Verifique os custos e condições do efeito que se ativa quando a carta é jogada.'],
    'When Attacking':['Ao declarar ataque','A ativação ocorre na declaração do ataque, não somente depois de causar dano.'],
    'Activate: Main':['Na sua fase principal','A habilidade é ativada na sua fase principal, fora de uma batalha, cumprindo seus custos.'],
    'Main':['Evento na fase principal','Observe o custo do Evento e resolva o efeito na janela permitida.'],
    'Counter':['Na etapa de defesa','Este marcador de Evento permite o uso na etapa de Counter, pagando os custos e condições indicados.'],
    'On K.O.':['Quando esta carta sofre K.O.','Enviar ao descarte por outro método não equivale necessariamente a sofrer K.O.'],
    'On Block':['Ao bloquear','Verifique o evento de ativação de Blocker indicado na carta.'],
    'End of Your Turn':['Ao fim do seu turno','Resolva o efeito na End Phase, seguindo os custos, condições e a ordem das regras.'],
    'End of Your Opponent\'s Turn':['Ao fim do turno adversário','O momento indicado é a End Phase do outro jogador.'],
    'On Your Opponent\'s Attack':['Quando o oponente ataca','A declaração de ataque do adversário é a janela mencionada pelo efeito.']
  };
  const colorNames={Red:'vermelha',Green:'verde',Blue:'azul',Purple:'roxa',Black:'preta',Yellow:'amarela'};
  const rarityNames={C:'Comum',UC:'Incomum',R:'Rara',SR:'Super Rara',SEC:'Secreta',L:'Líder',SP:'Especial'};
  const types={LEADER:'Líder',CHARACTER:'Personagem',EVENT:'Evento',STAGE:'Cenário',DON:'DON!!'};
  const num=value=>/^\d+$/.test(String(value??'').trim())?+value:null;
  const format=n=>Number(n).toLocaleString('pt-BR');
  function describe(card) {
    const text=(card.effect||'')+'\n'+(card.trigger||'');
    const color=card.color.split('/').map(x=>colorNames[x]||x).join(' e ');
    const cost=num(card.cost),power=num(card.power),counter=num(card.counter),life=num(card.life);
    let intro=`${card.name} é uma carta ${color} da categoria ${types[card.type]||card.type}. `;
    if(card.type==='LEADER')intro+=`${life===null?'Sua vida inicial não está informada numericamente.':`Começa com ${life} cartas de vida.`} ${power===null?'':`Tem ${format(power)} de poder base.`}`;
    else if(card.type==='CHARACTER')intro+=`${cost===null?'O custo não está informado numericamente na fonte.':`Seu custo impresso é ${cost} DON!!.`} ${power===null?'O poder não está informado numericamente neste registro.':`Entra com ${format(power)} de poder base.`}`;
    else if(card.type==='EVENT')intro+=`${cost===null?'O custo aparece sem valor numérico na fonte.':`O custo impresso é ${cost} DON!!.`} É usada na janela indicada pelo efeito e depois segue ao descarte conforme o procedimento.`;
    else if(card.type==='DON')intro=`${card.name} é uma carta de recurso DON!!. Ela pertence ao deck separado de dez DON!! e pode pagar custos ou ser atribuída conforme as regras. O aumento normal de +1000 de poder se aplica durante o seu turno.`;
    else intro+=`${cost===null?'Confira o custo no texto e na ilustração.':`Seu custo impresso é ${cost} DON!!.`} Ocupa a área de Cenário e oferece os efeitos descritos na carta.`;
    const tags=Object.keys(glossary).filter(k=>text.includes('['+k+']'));
    const windows=Object.entries(timings).filter(([k])=>(card.effect||'').includes('['+k+']')).map(([key,[label,explanation]])=>({key,label,explanation}));
    const hints=[];
    if(card.type==='CHARACTER')hints.push(counter===null?'Sem Counter numérico impresso neste registro: não conte com esta carta para aumentar a defesa pelo Counter de Personagem.':`Seu Counter +${format(counter)} pode ser usado da mão na etapa de defesa, sem pagar o custo de jogar o Personagem.`);
    if(card.type==='LEADER')hints.push('As cores deste Líder orientam a construção do deck. Confira também qualquer regra especial escrita no efeito.');
    if(text.includes('[Once Per Turn]'))hints.push('Há um limite de uma vez por turno no efeito indicado; ele não transforma todas as habilidades da carta em uma única ativação.');
    const don=(card.effect||'').match(/\[DON!! x(\d+)\]/);if(don)hints.push(`O trecho DON!! x${don[1]} exige essa quantidade de DON!! atribuída à carta para a condição indicada. Não significa pagar automaticamente esse número.`);
    if(card.trigger)hints.push('Esta impressão possui Trigger. Leia essa parte separadamente: o custo, o resultado ou a duração podem diferir do uso normal.');
    if((card.effect||'').includes('[Your Turn]'))hints.push('O marcador Your Turn limita a aplicação do trecho correspondente ao seu turno.');
    if((card.effect||'').includes('[Opponent\'s Turn]'))hints.push('O trecho Opponent’s Turn se aplica no turno do oponente, conforme o texto.');
    if(!card.effect?.trim())hints.push('Este registro não apresenta efeito impresso. Custo, poder, atributos e características ainda podem ser usados por efeitos de outras cartas.');
    if(card.type==='DON')hints.push('DON!! não integra as cinquenta cartas do deck principal. O recurso não tem a função de Personagem, Evento ou Cenário.');
    const characteristics=card.type==='DON'?[]:card.archetype.split('/').map(x=>x.trim()).filter(Boolean);
    const curated=editorial[card.id]||null;
    const focus=curated?.title||({LEADER:'A carta que define o rumo do seu deck.',CHARACTER:'Uma peça para conhecer antes de levar ao campo.',EVENT:'Uma jogada cujo momento faz a diferença.',STAGE:'Um apoio que permanece na sua rota.',DON:'Os recursos que sustentam sua aventura.'}[card.type]);
    const preview=curated?.text||(card.type==='LEADER'?`${life===null?'Vida a conferir':life+' de vida'} · ${power===null?'poder a conferir':format(power)+' de poder'}. ${windows[0]?.label||'Leia a habilidade deste Líder'}.`:card.type==='CHARACTER'?`${cost===null?'Custo a conferir':cost+' DON!!'} · ${power===null?'poder a conferir':format(power)+' de poder'}. ${counter===null?'Sem Counter numérico':'+ '+format(counter)+' de Counter'}${tags.length?' · '+tags.join(', '):''}.`:`${cost===null?'Custo a conferir':cost+' DON!!'}. ${windows.map(w=>w.label).join(' · ')||'Confira as condições do efeito'}${card.trigger?' · Possui Trigger.':'.'}`);
    const reading=curated?.text||`${characteristics.length?'As características impressas são '+characteristics.join(' e ')+'. Elas podem ser exigidas por outras habilidades; não substituem a categoria da carta. ':''}${windows.length?'O texto possui as seguintes janelas: '+windows.map(w=>w.label.toLowerCase()).join('; ')+'. Confira os custos e condições de cada trecho. ':card.effect?.trim()?'Leia as condições do efeito antes de definir quando ele se aplica. ':'O registro não apresenta efeito impresso; os demais campos ainda podem participar de interações. '}${card.trigger?'Há um Trigger separado do efeito normal.':''}`;
    return {intro:intro.trim(),reading:card.type==='DON'?'A arte identifica a edição ou distribuição do recurso. Para jogar, o deck de DON!! contém dez cartas, separado do deck principal. Compare o idioma e a impressão com as regras do seu evento.':reading,focus,preview:card.type==='DON'?'Recurso do deck separado de dez DON!!. Atribuído, fornece o aumento normal de +1000 de poder durante o seu turno.':preview,curated,hints,timings:windows,keywords:tags.map(k=>({key:k,title:glossary[k][0],text:glossary[k][1]})),characteristics,rarity:rarityNames[card.rarity]||card.rarity};
  }
  window.AtlasDescriptions={describe,editorialCount:Object.keys(editorial).length};
})();
